mapper.select:
SELECT
just.ADJUST_ID AS adjustId,
just.DESIGN_ID AS designId,
just.ADJUST_CODE AS adjustCode,
just.ADJUST_NAME AS adjustName,
just.STATUS AS status,
just.JC_ID AS jcId,
just.JC_CODE AS jcCode,
just.NUM AS num,
just.EXECUTE_DATE_START AS executeDateStart,
just.EXECUTE_DATE_END AS executeDateEnd,
just.ADJUST_TYPE AS adjustType,
plan.DESIGN_ID AS designId,
just.LAST_UPDATE_DATE AS lastUpdateDate,
just.CREATED_BY AS createdBy,
just.CREATION_DATE AS creationDate,
just.CREATE_UNIT_ID AS createUnitId,
just.CREATE_UNIT_CODE AS createUnitCode,
just.CREATE_UNIT_NAME AS createUnitName,
just.CREATED_FULL_NAME AS createdFullName
FROM
scc_sou_ch_paa_adjust just left join scc_sou_ch_design_plan plan
ON just.JC_ID = plan.PROJECT_ID


        AND just.ADJUST_CODE = #{obj.adjustCode,jdbcType=VARCHAR}


        AND just.ADJUST_NAME = #{obj.adjustName,jdbcType=VARCHAR}


        AND just.CREATED_BY = #{obj.createdBy,jdbcType=VARCHAR}


        AND just.CREATION_DATE = #{obj.creationDate,jdbcType=TIMESTAMP}


        AND just.EXECUTE_DATE_START >= #{obj.executeDateStart,jdbcType=TIMESTAMP}


        AND just.EXECUTE_DATE_END <= #{obj.executeDateEnd,jdbcType=TIMESTAMP}


        AND just.JC_ID = #{obj.jcId,jdbcType=VARCHAR}


        AND just.JC_CODE = #{obj.jcCode,jdbcType=VARCHAR}


        AND just.STATUS = #{obj.status,jdbcType=VARCHAR}


        AND just.CREATE_UNIT_ID = #{obj.createUnitId,jdbcType=VARCHAR}


        AND just.CREATE_UNIT_CODE = #{obj.createUnitCode,jdbcType=VARCHAR}


        AND just.CREATE_UNIT_NAME = #{obj.createUnitName,jdbcType=VARCHAR}


        AND just.CREATED_FULL_NAME = #{obj.createdFullName,jdbcType=VARCHAR}


        AND just.ADJUST_TYPE = #{obj.adjustType,jdbcType=VARCHAR}
